function visibleToRight(heights: number[]): number[] {
  const n = heights.length, ans = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    let tallestBetween = 0;
    for (let j = i + 1; j < n; j++) {
      if (heights[j] > tallestBetween) ans[i]++;
      if (heights[j] > heights[i]) break;
      tallestBetween = Math.max(tallestBetween, heights[j]);
    }
  }
  return ans;
}

