    def visibleToRight(self, heights: List[int]) -> List[int]:
        n = len(heights)
        ans = [0] * n
        for i in range(n):
            tallest_between = 0
            for j in range(i + 1, n):
                if heights[j] > tallest_between:
                    ans[i] += 1
                if heights[j] > heights[i]:
                    break
                tallest_between = max(tallest_between, heights[j])
        return ans

