function visibleToRight(heights: number[]): number[] {
  const n = heights.length, ans = new Array(n).fill(0), stack: number[] = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length && stack[stack.length - 1] < heights[i]) {
      stack.pop();
      ans[i]++;
    }
    if (stack.length) ans[i]++; // the first taller person
    stack.push(heights[i]);
  }
  return ans;
}

