        ans = [0] * len(heights)
        stack = []
        for i in range(len(heights) - 1, -1, -1):
            h = heights[i]
            while stack and stack[-1] < h:
                stack.pop()
                ans[i] += 1
            if stack:
                ans[i] += 1  # the first taller person
            stack.append(h)
        return ans

